export type ThemePreset = typeof THEME_PRESETS[number];

function hexToThemeVars(hex: string) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  const sc = (v: number, f: number) => Math.round(Math.min(255, Math.max(0, v * f))).toString(16).padStart(2, '0');
  const lt = (v: number, f: number) => Math.round(Math.min(255, v + (255 - v) * f)).toString(16).padStart(2, '0');
  return {
    g1: `#${sc(r,0.70)}${sc(g,0.70)}${sc(b,0.70)}`,
    g2: hex,
    g3: `#${lt(r,0.18)}${lt(g,0.18)}${lt(b,0.18)}`,
    g4: `#${lt(r,0.40)}${lt(g,0.40)}${lt(b,0.40)}`,
    gold: hex,
    crimson: `#${sc(r,0.70)}${sc(g,0.70)}${sc(b,0.70)}`,
    rose: `#${lt(r,0.80)}${lt(g,0.80)}${lt(b,0.80)}`,
  };
}

function applyCustomThemeHex(hex: string) {
  const v = hexToThemeVars(hex);
  const root = document.documentElement;
  root.style.setProperty('--brand-g1', v.g1);
  root.style.setProperty('--brand-g2', v.g2);
  root.style.setProperty('--brand-g3', v.g3);
  root.style.setProperty('--brand-g4', v.g4);
  root.style.setProperty('--color-brand-gold', v.gold);
  root.style.setProperty('--color-brand-crimson', v.crimson);
  root.style.setProperty('--color-brand-rose', v.rose);
  saveBrandVarsCache({ g1: v.g1, g2: v.g2, g3: v.g3, g4: v.g4, gold: v.gold, crimson: v.crimson, rose: v.rose });
}

const THEME_VARS_KEY = 'linq_brand_vars';

function saveBrandVarsCache(vars: { g1: string; g2: string; g3: string; g4: string; gold: string; crimson: string; rose: string }) {
  try { localStorage.setItem(THEME_VARS_KEY, JSON.stringify(vars)); } catch {}
}

function storeFallbackImg(name?: string | null, color?: string | null): string {
  if (!name) return '';
  const letter = name[0].toUpperCase();
  const bg = color || '#2563EB';
  return `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="${bg}"/><text x="50" y="67" text-anchor="middle" font-family="system-ui,sans-serif" font-weight="800" font-size="50" fill="rgba(255,255,255,0.9)">${letter}</text></svg>`)}`;
}

export function applyBrandTheme(t: ThemePreset) {
  const r = document.documentElement;
  r.style.setProperty('--color-brand-gold', t.gold);
  r.style.setProperty('--color-brand-crimson', t.crimson);
  r.style.setProperty('--color-brand-rose', t.rose);
  r.style.setProperty('--brand-g1', t.g1);
  r.style.setProperty('--brand-g2', t.g2);
  r.style.setProperty('--brand-g3', t.g3);
  r.style.setProperty('--brand-g4', t.g4);
  saveBrandVarsCache({ g1: t.g1, g2: t.g2, g3: t.g3, g4: t.g4, gold: t.gold, crimson: t.crimson, rose: t.rose });
}

