function UserStickerPanel({ uid, isOwnProfile = false, onOpenPack }: {
  uid: string;
  isOwnProfile?: boolean;
  onOpenPack?: (stickers: CollectibleSticker[]) => void;
}) {
  const [col, setCol] = useState<{ stickers: CollectibleSticker[]; revealedIds: string[]; uniqueTiers: StickerTier[] } | null>(null);
  const [showCollection, setShowCollection] = useState(false);
  const [expandedSticker, setExpandedSticker] = useState<CollectibleSticker | null>(null);
  const [cardDefs, setCardDefs] = useState<CollectibleCardDef[]>([]);

  useEffect(() => {
    getDocs(collection(db, 'collectible_cards')).then(snap => {
      setCardDefs(snap.docs.map(d => ({ id: d.id, ...d.data() } as CollectibleCardDef)));
    }).catch(console.error);
  }, []);

  useEffect(() => {
    return onSnapshot(doc(db, 'user_stickers', uid), snap => {
      if (snap.exists()) {
        const d = snap.data();
        setCol({ stickers: d.stickers || [], revealedIds: d.revealedIds || [], uniqueTiers: d.uniqueTiers || [] });
      } else {
        setCol(null);
      }
    });
  }, [uid]);

  const handleReveal = async (stickerId: string) => {
    if (!col) return;
    await updateDoc(doc(db, 'user_stickers', uid), { revealedIds: arrayUnion(stickerId) });
  };

  // Only show cards with actual artwork — skip emoji-only and broken-image stickers
  const validStickers = col ? col.stickers.filter(s => !!s.cardDefId && !!s.cardImageUrl) : [];

  if (!col || validStickers.length === 0) return null;

  const unrevealed = col.stickers.filter(s => !col.revealedIds.includes(s.id));
  const revealed = validStickers.filter(s => col.revealedIds.includes(s.id)).reverse();

  return (
    <>
      <div className="space-y-2">
        {/* Header */}
        <div className="flex items-center justify-between px-1">
          <p className="text-[10px] font-bold uppercase tracking-widest text-brand-navy/75">
            Cards <span className="text-brand-navy/40 normal-case tracking-normal font-bold">{validStickers.length}</span>
          </p>
          <button onClick={() => setShowCollection(true)} className="text-[10px] font-bold text-brand-navy/50 active:opacity-60">
            See all
          </button>
        </div>

        {/* Open pack CTA */}
        {isOwnProfile && unrevealed.length > 0 && (
          <motion.button
            className="w-full py-3 rounded-2xl font-bold text-sm flex items-center justify-center gap-2"
            style={{ background: 'linear-gradient(135deg, #0D0D2B, #1A0730)', color: 'white' }}
            onClick={() => onOpenPack?.(unrevealed)}
            whileTap={{ scale: 0.97 }}
            animate={{ boxShadow: ['0 0 0px #F5C51800', '0 0 18px #F5C51866', '0 0 0px #F5C51800'] }}
            transition={{ duration: 2, repeat: Infinity }}
          >
            🎴 Open {unrevealed.length} card{unrevealed.length !== 1 ? 's' : ''}
          </motion.button>
        )}

        {/* Slider */}
        <div className="flex gap-2 overflow-x-auto snap-x snap-mandatory -mx-4 px-4 pb-2 scrollbar-hide">
          {revealed.map(s => (
            <div key={s.id} className="snap-start shrink-0">
              <StickerCard sticker={s} isRevealed={true} size="sm" onExpand={() => setExpandedSticker(s)} />
            </div>
          ))}
        </div>
      </div>

      <AnimatePresence>
        {showCollection && (
          <UserCollectionModal
            uid={uid}
            isOwnProfile={isOwnProfile}
            stickers={col.stickers}
            revealedIds={col.revealedIds}
            onReveal={handleReveal}
            onClose={() => setShowCollection(false)}
            onOpenPack={onOpenPack}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {expandedSticker && (() => {
          const ecfg = STICKER_CONFIG[expandedSticker.tier];
          const eDef = expandedSticker.cardDefId ? cardDefs.find(d => d.id === expandedSticker.cardDefId) : null;
          return (
            <motion.div
              className="fixed inset-0 z-[400] flex items-center justify-center"
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              onClick={() => setExpandedSticker(null)}
            >
              <div className="absolute inset-0 bg-black/75 backdrop-blur-md" />
              <motion.div
                className="relative z-10 flex flex-col items-center gap-5"
                initial={{ scale: 0.4, y: 60, opacity: 0 }}
                animate={{ scale: 1, y: 0, opacity: 1 }}
                exit={{ scale: 0.4, y: 60, opacity: 0 }}
                transition={{ type: 'spring', damping: 18, stiffness: 220 }}
                onClick={e => e.stopPropagation()}
              >
                {/* Tier glow */}
                <motion.div style={{
                  position: 'absolute', inset: -32, borderRadius: 48,
                  background: ecfg.solid, filter: 'blur(48px)', zIndex: 0, opacity: 0.45,
                }}
                  animate={{ opacity: [0.3, 0.6, 0.3], scale: [0.9, 1.1, 0.9] }}
                  transition={{ duration: 2, repeat: Infinity }}
                />
                <StickerCard sticker={expandedSticker} isRevealed={true} size="lg" />
                {eDef?.description && (
                  <p className="relative z-10 text-center text-sm text-white/80 max-w-[220px] leading-snug">{eDef.description}</p>
                )}
                <div className="relative z-10 flex gap-3">
                  <div className="relative inline-flex flex-col items-center">
                    <button disabled className="px-8 py-2.5 rounded-2xl font-bold text-sm text-white cursor-not-allowed"
                      style={{ background: '#3b82f6' }}>
                      Trade
                    </button>
                    <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[8px] font-black px-1.5 py-0.5 rounded-full leading-none">
                      Coming soon
                    </span>
                  </div>
                </div>
                <button
                  className="relative z-10 px-8 py-3 rounded-2xl font-bold text-sm text-white/70"
                  style={{ background: 'rgba(255,255,255,0.10)', border: '1px solid rgba(255,255,255,0.16)' }}
                  onClick={() => setExpandedSticker(null)}
                >Close</button>
              </motion.div>
            </motion.div>
          );
        })()}
      </AnimatePresence>
    </>
  );
}

