// Mystery card used inside PackOpeningModal — larger, dramatic reveal
function MysteryRevealCard({ sticker, isRevealed, onReveal }: {
  sticker: CollectibleSticker; isRevealed: boolean; onReveal?: () => void;
}) {
  const [localRevealed, setLocalRevealed] = useState(isRevealed);
  const [flipping, setFlipping] = useState(false);
  const [showFlash, setShowFlash] = useState(false);
  const cfg = STICKER_CONFIG[sticker.tier];
  // slow anticipation rotation before reveal
  const [rotDir] = useState(() => (Math.random() > 0.5 ? 1 : -1));

  useEffect(() => { if (isRevealed) setLocalRevealed(true); }, [isRevealed]);

  const handleTap = () => {
    if (localRevealed || !onReveal || flipping) return;
    setFlipping(true);
  };

  return (
    <motion.div
      onClick={handleTap}
      animate={flipping ? { scale: [1, 1.3, 0.88, 1.12, 1] } : { scale: 1 }}
      transition={{ duration: 0.48 }}
      onAnimationComplete={() => {
        if (flipping) {
          setFlipping(false);
          setLocalRevealed(true);
          setShowFlash(true);
          setTimeout(() => setShowFlash(false), 380);
          onReveal?.();
        }
      }}
      style={{ width: 140, height: 192, perspective: '1000px', position: 'relative',
        cursor: localRevealed ? 'default' : 'pointer', flexShrink: 0 }}
    >
      {/* Unrevealed glow pulse */}
      {!localRevealed && (
        <motion.div style={{
          position: 'absolute', inset: -10, borderRadius: 32, zIndex: 0,
          background: `radial-gradient(circle, ${cfg.solid}99 0%, transparent 70%)`,
          filter: 'blur(10px)',
        }}
          animate={{ opacity: [0.3, 0.9, 0.3], scale: [0.92, 1.08, 0.92] }}
          transition={{ duration: 1.5, repeat: Infinity }}
        />
      )}
      {/* Tier glow after reveal */}
      {localRevealed && (
        <motion.div style={{
          position: 'absolute', inset: -8, borderRadius: 30, zIndex: 0,
          background: cfg.solid, filter: 'blur(20px)',
        }}
          initial={{ opacity: 0 }} animate={{ opacity: 0.55 }}
          transition={{ duration: 0.4 }}
        />
      )}

      {/* Slow anticipation rotate wrapper — stops after reveal */}
      <motion.div
        animate={!localRevealed ? { rotate: [0, rotDir * 7, 0, rotDir * -5, 0, rotDir * 4, 0] } : { rotate: 0 }}
        transition={!localRevealed ? { duration: 4.5, repeat: Infinity, ease: 'easeInOut' } : { duration: 0.3 }}
        style={{ width: '100%', height: '100%', position: 'absolute', inset: 0, zIndex: 1 }}
      >
      <motion.div
        initial={{ rotateY: isRevealed ? 180 : 0 }}
        animate={{ rotateY: localRevealed ? 180 : 0 }}
        transition={{ duration: 0.68, ease: [0.23, 1, 0.32, 1] }}
        style={{ transformStyle: 'preserve-3d', WebkitTransformStyle: 'preserve-3d', width: '100%', height: '100%', position: 'relative' }}
      >
        {/* Front — mystery with tier-color border hint */}
        <div style={{
          position: 'absolute', inset: 0, backfaceVisibility: 'hidden', WebkitBackfaceVisibility: 'hidden',
          background: 'linear-gradient(148deg, #16103A, #2B1458)',
          border: `2.5px solid ${cfg.border}`, borderRadius: 20,
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 8,
          overflow: 'hidden',
          boxShadow: `0 0 18px ${cfg.color}55, inset 0 0 12px rgba(0,0,0,0.4)`,
        }}>
          {/* Tier label hint top — hidden on tap */}
          {!flipping && !localRevealed && (
            <div style={{ position: 'absolute', top: 8, left: 0, right: 0, textAlign: 'center', zIndex: 3 }}>
              <span style={{ fontSize: 8, fontWeight: 900, letterSpacing: '0.18em', color: cfg.border, textTransform: 'uppercase' }}>{cfg.label}</span>
            </div>
          )}
          {/* Shimmer sweep */}
          <motion.div style={{
            position: 'absolute', inset: 0, borderRadius: 18,
            background: 'linear-gradient(108deg, transparent 32%, rgba(255,255,255,0.13) 50%, transparent 68%)',
            backgroundSize: '300% 100%',
          }}
            animate={{ backgroundPosition: ['-200% 0', '300% 0'] }}
            transition={{ duration: 2.0, repeat: Infinity, ease: 'linear' }}
          />
          {/* Rotating rings */}
          <motion.div style={{
            position: 'absolute', width: 110, height: 110, borderRadius: '50%',
            border: `1.5px solid ${cfg.border}44`,
          }}
            animate={{ rotate: 360 }}
            transition={{ duration: 5, repeat: Infinity, ease: 'linear' }}
          />
          <motion.div style={{
            position: 'absolute', width: 75, height: 75, borderRadius: '50%',
            border: `1.5px solid ${cfg.border}33`,
          }}
            animate={{ rotate: -360 }}
            transition={{ duration: 3.5, repeat: Infinity, ease: 'linear' }}
          />
          {/* Question mark — hidden instantly on tap */}
          {!flipping && !localRevealed && (<>
          <motion.div style={{ fontSize: 64, lineHeight: 1, color: cfg.border, fontWeight: 900,
            filter: `drop-shadow(0 0 20px ${cfg.color}cc)`, zIndex: 2 }}
            animate={{ scale: [1, 1.12, 1], opacity: [0.75, 1, 0.75] }}
            transition={{ duration: 1.4, repeat: Infinity }}
          >?</motion.div>
          <motion.div style={{ fontSize: 9, color: cfg.border, fontWeight: 800,
            letterSpacing: '0.16em', zIndex: 2, opacity: 0.8 }}
            animate={{ opacity: [0.35, 1, 0.35] }}
            transition={{ duration: 1.1, repeat: Infinity, delay: 0.4 }}
          >TAP TO REVEAL</motion.div>
          </>)}
        </div>

        {/* Back — card reveal, matches expanded card format */}
        <div style={{
          position: 'absolute', inset: 0, backfaceVisibility: 'hidden', WebkitBackfaceVisibility: 'hidden',
          transform: 'rotateY(180deg)', borderRadius: 20,
        }}>
          {showFlash && (
            <motion.div style={{ position: 'absolute', inset: 0, background: 'white', borderRadius: 18, zIndex: 20 }}
              initial={{ opacity: 0.9 }} animate={{ opacity: 0 }} transition={{ duration: 0.38 }}
            />
          )}
          {/* Holo outer border */}
          <div className="holo-border" style={{ position: 'absolute', inset: 0, padding: 3, borderRadius: 18, boxShadow: `0 8px 36px ${cfg.color}66` }}>
            {/* Thick tier-colour inner border */}
            <div style={{ width: '100%', height: '100%', padding: 10, borderRadius: 15, background: cfg.border }}>
              {/* Card content */}
              <div style={{ width: '100%', height: '100%', borderRadius: 5, overflow: 'hidden', display: 'flex', flexDirection: 'column', background: '#fff', position: 'relative' }}>
                <div style={{ flex: 1, overflow: 'hidden', borderBottom: `2px solid ${cfg.border}` }}>
                  {sticker.cardImageUrl
                    ? <img src={sticker.cardImageUrl} alt={sticker.cardName} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
                    : <div style={{ width: '100%', height: '100%', background: cfg.solid, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <span style={{ fontSize: 40 }}>{STICKER_CONFIG[sticker.tier].variants[sticker.variant ?? 0]?.emoji}</span>
                      </div>
                  }
                </div>
                {/* Bottom panel */}
                <div style={{ height: 30, background: cfg.bg, padding: '3px 8px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 4, flexShrink: 0 }}>
                  <span style={{ fontSize: 10, fontWeight: 900, color: cfg.color, flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' as const }}>{sticker.cardName || cfg.label}</span>
                  <span style={{ fontSize: 8, fontWeight: 900, color: cfg.color, opacity: 0.75, flexShrink: 0 }}>{cfg.label}</span>
                </div>
                {/* White shine sweep */}
                <div className="holo-card-shine" />
              </div>
            </div>
          </div>
        </div>
      </motion.div>
      </motion.div>{/* end slow-rotation wrapper */}
    </motion.div>
  );
}

