// --- Physical Card QR Scan ---

async function processPhysicalCardScan(
  physicalCardId: string,
  user: FirebaseUser,
): Promise<{ sticker: CollectibleSticker; alreadyClaimed: boolean } | { error: string }> {
  const cardRef = doc(db, 'physical_cards', physicalCardId);
  const cardSnap = await getDoc(cardRef).catch(() => null);
  if (!cardSnap?.exists()) return { error: 'Card not found. Make sure you scanned the right QR code.' };
  const data = cardSnap.data();

  const userStickersRef = doc(db, 'user_stickers', user.uid);
  const userStickersSnap = await getDoc(userStickersRef).catch(() => null);
  const alreadyClaimed = (userStickersSnap?.data()?.claimedPhysicalCardIds || []).includes(physicalCardId);

  const sticker: CollectibleSticker = {
    id: (crypto as any).randomUUID?.() || Math.random().toString(36).slice(2),
    tier: data.tier as StickerTier,
    variant: 0,
    earnedAt: new Date().toISOString(),
    cardDefId: data.cardDefId,
    cardImageUrl: data.cardImageUrl,
    cardName: data.cardDefName,
  };

  if (!alreadyClaimed) {
    if (userStickersSnap?.exists()) {
      await updateDoc(userStickersRef, {
        stickers: arrayUnion(sticker),
        revealedIds: arrayUnion(sticker.id),
        uniqueTiers: arrayUnion(sticker.tier),
        claimedPhysicalCardIds: arrayUnion(physicalCardId),
      });
    } else {
      await setDoc(userStickersRef, {
        user_id: user.uid,
        stickers: [sticker],
        revealedIds: [sticker.id],
        uniqueTiers: [sticker.tier],
        claimedPhysicalCardIds: [physicalCardId],
      });
    }

    // Also write to any active collectible challenge sticker_cards
    try {
      const stickerCardsSnap = await getDocs(query(collection(db, 'sticker_cards'), where('user_id', '==', user.uid)));
      if (!stickerCardsSnap.empty) {
        const programmeIds = [...new Set(stickerCardsSnap.docs.map(d => d.data().programme_id as string))];
        const activePids = new Set<string>();
        await Promise.all(programmeIds.map(async pid => {
          const cSnap = await getDoc(doc(db, 'challenges', pid));
          if (cSnap.exists() && cSnap.data().status === 'active' && cSnap.data().type === 'collectible') activePids.add(pid);
        }));
        const activeDocs = stickerCardsSnap.docs.filter(d => activePids.has(d.data().programme_id));
        if (activeDocs.length > 0) {
          const userName = user.displayName || '';
          await Promise.all(activeDocs.map(d => updateDoc(d.ref, { stickers: arrayUnion(sticker), userName })));
        }
      }
    } catch { /* challenge write is non-critical */ }

    logEvent('physical_card_scanned', user.uid, { physicalCardId, cardDefId: data.cardDefId, tier: data.tier });
  }

  return { sticker, alreadyClaimed };
}

// --- NFC Stamp Modal ---

async function processNFCStamp(storeId: string, user: FirebaseUser, profile: UserProfile | null,
  onStatus: (state: 'processing' | 'success' | 'error', msg: string) => void, qty = 1): Promise<CollectibleSticker[]> {
  onStatus('processing', 'Verifying stamp...');
  try {
    const storeSnap = await getDoc(doc(db, 'stores', storeId));
    if (!storeSnap.exists()) { onStatus('error', 'Store not found. Please try again.'); return []; }

    const store = { id: storeSnap.id, ...storeSnap.data() } as StoreProfile;
    const limit = store.stamps_required_for_reward || 10;
    const cardId = `${user.uid}_${store.id}`;
    const cardRef = doc(db, 'cards', cardId);
    const cardSnap = await getDoc(cardRef);
    const prevCardData = cardSnap.exists() && !cardSnap.data()?.isArchived ? cardSnap.data() : null;

    const userName = profile?.name || user.displayName || user.email?.split('@')[0] || 'Customer';
    const userPhoto = profile?.photoURL || user.photoURL || '';
    let newStamps: number;
    let newCycles: number;

    if (!cardSnap.exists() || cardSnap.data()?.isArchived) {
      newStamps = Math.min(qty, limit); newCycles = 0;
      await setDoc(cardRef, {
        user_id: user.uid, store_id: store.id, current_stamps: newStamps,
        total_completed_cycles: newCycles, stamps_required: limit,
        last_tap_timestamp: serverTimestamp(), isArchived: false, isRedeemed: false, userName, userPhoto,
        storeName: store.name, storeLogoUrl: store.logoUrl || '', storeTheme: store.theme || '',
        createdAt: serverTimestamp(),
      });
      await updateDoc(doc(db, 'users', user.uid), { total_cards_held: increment(1) });
    } else {
      const current = cardSnap.data()?.current_stamps || 0;
      newCycles = cardSnap.data()?.total_completed_cycles || 0;
      newStamps = current + qty;
      const cycleComplete = newStamps >= limit;
      if (cycleComplete) {
        newCycles += 1;
        if (newStamps > limit) newStamps = limit;
      }
      const txData1 = cycleComplete
        ? { user_id: user.uid, store_id: store.id, completed_at: serverTimestamp(), stamp_count: qty, stamps_at_completion: limit, reward_claimed: false, userName, userPhoto }
        : { user_id: user.uid, store_id: store.id, completed_at: serverTimestamp(), stamp_count: qty, userName, userPhoto };
      await addDoc(collection(db, 'transactions'), txData1);
      await updateDoc(cardRef, { current_stamps: newStamps, total_completed_cycles: newCycles, last_tap_timestamp: serverTimestamp() });
    }

    await updateDoc(doc(db, 'users', user.uid), { totalStamps: increment(qty), lastStampAt: serverTimestamp() });
    bumpStreak(user.uid).catch(console.error);
    logEvent('stamp_issued', user.uid, { storeId: store.id, cardId, stampCount: qty, method: 'nfc', ...stampEventMeta(store, prevCardData, newStamps) });
    if (newStamps >= store.stamps_required_for_reward || 0) {
      logEvent('card_completed', user.uid, { storeId: store.id, cardId, totalStamps: store.stamps_required_for_reward || 10 });
    }

    // Update avatar mood on every stamp (food stores give a bigger boost)
    if (store.category === 'Food') {
      getDoc(doc(db, 'users', user.uid)).then(snap => {
        const cur = (snap.data()?.avatar?.mood ?? 50) as number;
        const today = new Date().toISOString().slice(0, 10);
        updateDoc(doc(db, 'users', user.uid), {
          'avatar.mood': Math.min(100, cur + 6),
          'avatar.lastFoodStampDate': today,
        }).catch(console.error);
      }).catch(console.error);
    } else {
      getDoc(doc(db, 'users', user.uid)).then(snap => {
        const cur = (snap.data()?.avatar?.mood ?? 50) as number;
        updateDoc(doc(db, 'users', user.uid), {
          'avatar.mood': Math.min(100, cur + 3),
        }).catch(console.error);
      }).catch(console.error);
    }

    const newStickers = await issueUserStickers(user.uid, userName, 3).catch(() => [] as CollectibleSticker[]);
    updateChallengeProgress(user.uid, store.id, 1).catch(console.error);

    // Also issue membership points if store has a visit-type membership card
    if (store.membershipEnabled && store.membershipType === 'visit') {
      const membershipId = `${user.uid}_${store.id}_membership`;
      const memSnap = await getDoc(doc(db, 'cards', membershipId));
      if (memSnap.exists() && !memSnap.data()?.isArchived) {
        const stampsPerVisit = store.membershipStampsPerVisit || 1;
        await updateDoc(doc(db, 'cards', membershipId), {
          membership_visits: increment(stampsPerVisit),
          total_points_earned: increment(stampsPerVisit),
          last_transaction_at: serverTimestamp(),
        });
        await addDoc(collection(db, 'transactions'), {
          user_id: user.uid, store_id: store.id,
          card_type: 'membership', membership_type: 'visit',
          type: 'nfc_co_issue', points_earned: stampsPerVisit, issued_at: serverTimestamp(),
        });
      }
    }

    // Record scan location for fraud detection (fire-and-forget)
    Promise.all([
      getScanLocation(),
      (async (): Promise<{ lat: number; lng: number } | null> => {
        // 1. top-level lat/lng
        if (store.lat && store.lng) return { lat: store.lat, lng: store.lng };
        // 2. first location entry
        const loc = store.locations?.find(l => l.lat && l.lng);
        if (loc?.lat && loc?.lng) return { lat: loc.lat, lng: loc.lng };
        // 3. geocode the address as last resort
        const addr = store.address || store.location || '';
        if (addr) return geocodeAddressGlobal(addr);
        return null;
      })(),
    ]).then(([userCoords, storeCoords]) => {
      const distanceKm = (userCoords && storeCoords)
        ? haversineKm(userCoords.lat, userCoords.lng, storeCoords.lat, storeCoords.lng)
        : null;
      addDoc(collection(db, 'scan_logs'), {
        userId: user.uid,
        userName,
        storeId: store.id,
        storeName: store.name,
        scannedAt: serverTimestamp(),
        userLat: userCoords?.lat ?? null,
        userLng: userCoords?.lng ?? null,
        storeLat: storeCoords?.lat ?? null,
        storeLng: storeCoords?.lng ?? null,
        distanceKm,
      }).catch(console.error);
    }).catch(console.error);

    onStatus('success', `Stamp added at ${store.name}!`);
    return newStickers;
  } catch (err: any) {
    console.error('NFC stamp error:', err);
    onStatus('error', err?.message || 'Something went wrong. Please try again.');
    return [];
  }
}

