function SettingsMenu({
  isOpen,
  onClose,
  profile,
  userCards,
  isAdmin,
  onOpenAdmin,
  onOpenStores,
}: {
  isOpen: boolean,
  onClose: () => void,
  profile: UserProfile | null,
  userCards: Card[],
  isAdmin?: boolean,
  onOpenAdmin?: () => void,
  onOpenStores?: () => void,
}) {
  const [showArchive, setShowArchive] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [archivedCards, setArchivedCards] = useState<Card[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [storeCache, setStoreCache] = useState<Map<string, StoreProfile>>(new Map());

  useEffect(() => {
    if (!profile) return;
    const aq = query(collection(db, 'cards'), where('user_id', '==', profile.uid), where('isArchived', '==', true));
    const unsubArchive = onSnapshot(aq, (snap) => {
      setArchivedCards(snap.docs.map(d => ({ id: d.id, ...d.data() } as Card)));
    }, (error) => console.error("SettingsMenu archive listener:", error));

    const hq = query(collection(db, 'transactions'), where('user_id', '==', profile.uid), orderBy('completed_at', 'desc'));
    const unsubHistory = onSnapshot(hq, (snap) => {
      setTransactions(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    }, (error) => console.error("SettingsMenu history listener:", error));

    return () => {
      unsubArchive();
      unsubHistory();
    };
  }, [profile?.uid]);

  // Fetch any stores not yet cached when archive or history modals open
  useEffect(() => {
    if (!showArchive && !showHistory) return;
    const needed = [...new Set([
      ...archivedCards.map(c => c.store_id),
      ...transactions.map(t => t.store_id),
    ])].filter(id => id && !storeCache.has(id));
    if (needed.length === 0) return;
    Promise.all(needed.map(id => getDoc(doc(db, 'stores', id)))).then(snaps => {
      setStoreCache(prev => {
        const next = new Map(prev);
        snaps.forEach(s => { if (s.exists()) next.set(s.id, { id: s.id, ...s.data() } as StoreProfile); });
        return next;
      });
    }).catch(() => {});
  }, [showArchive, showHistory, archivedCards, transactions]);


  return (
    <motion.div 
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[100] bg-brand-navy/60 backdrop-blur-sm flex items-end justify-center"
      onClick={onClose}
    >
      <motion.div 
        initial={{ y: "100%" }}
        animate={{ y: 0 }}
        exit={{ y: "100%" }}
        className="glass-panel w-full max-w-md rounded-t-[3rem] p-8 space-y-6 max-h-[90vh] overflow-y-auto"
        onClick={e => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-2">
          <h2 className="font-display text-2xl font-bold">Menu</h2>
          <button onClick={onClose} className="p-2 bg-brand-navy/5 rounded-full">
            <X size={20} />
          </button>
        </div>

        <div className="space-y-3">
          <MenuButton icon={<Archive />} label="Archived Cards" sub="View completed programs" onClick={() => setShowArchive(true)} />
          <MenuButton icon={<Clock />} label="Stamp History" sub="Timeline of collections" onClick={() => setShowHistory(true)} />
          <MenuButton icon={<Settings />} label="Settings" sub="Account preferences" />
          {isAdmin && (
            <MenuButton icon={<Flag />} label="Admin Panel" sub="Challenges, badges & settings" onClick={onOpenAdmin} />
          )}
        </div>

        <AnimatePresence>
          {showArchive && (
            <Modal title="Archived Cards" onClose={() => setShowArchive(false)}>
              <div className="space-y-3">
                {archivedCards.map(card => {
                  const store = storeCache.get(card.store_id);
                  const completedAt = (card as any).last_tap_timestamp;
                  return (
                    <div key={card.id} className="glass-card p-4 rounded-2xl flex items-center gap-3">
                      <div className="w-11 h-11 rounded-xl overflow-hidden bg-brand-navy/5 shrink-0 flex items-center justify-center">
                        {store?.logoUrl
                          ? <img src={store.logoUrl} alt="" className="w-full h-full object-cover" />
                          : <Archive size={18} className="text-brand-navy/30" />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-bold text-sm truncate">{store?.name || 'Unknown Store'}</p>
                        <p className="text-[11px] text-brand-navy/75">
                          {(card.total_completed_cycles || 1)}× completed
                          {store?.reward ? ` · ${store.reward}` : ''}
                        </p>
                        {completedAt && (
                          <p className="text-[10px] text-brand-navy/40 mt-0.5">
                            {format(completedAt.toDate(), 'MMM d, yyyy')}
                          </p>
                        )}
                      </div>
                      <span className="text-[9px] font-bold text-brand-gold bg-brand-gold/10 px-2 py-1 rounded-full shrink-0">DONE</span>
                    </div>
                  );
                })}
                {archivedCards.length === 0 && (
                  <div className="py-12 text-center text-brand-navy/32">
                    <Archive size={48} className="mx-auto mb-4 opacity-10" />
                    <p className="font-bold">No archived cards yet</p>
                  </div>
                )}
              </div>
            </Modal>
          )}

          {showHistory && (
            <Modal title="Stamp History" onClose={() => setShowHistory(false)}>
              <div className="space-y-0">
                {transactions.map((tx, i) => {
                  const store = storeCache.get(tx.store_id);
                  const isCompletion = !!tx.stamps_at_completion;
                  const ts = tx.completed_at || tx.issued_at;
                  return (
                    <div key={tx.id} className="flex gap-3">
                      <div className="flex flex-col items-center">
                        <div className={cn(
                          'w-8 h-8 rounded-full flex items-center justify-center shrink-0',
                          isCompletion ? 'bg-brand-gold text-brand-navy' : 'bg-brand-navy/8 text-brand-navy/60'
                        )}>
                          {isCompletion ? <CheckCircle2 size={15} /> : <Star size={14} />}
                        </div>
                        {i < transactions.length - 1 && <div className="w-0.5 flex-1 bg-brand-navy/5 my-1" />}
                      </div>
                      <div className="flex-1 pb-5 min-w-0">
                        <div className="flex items-center gap-2 min-w-0">
                          {store?.logoUrl && (
                            <img src={store.logoUrl} alt="" className="w-5 h-5 rounded-md object-cover shrink-0" />
                          )}
                          <p className="font-bold text-sm truncate">{store?.name || 'Unknown Store'}</p>
                        </div>
                        <p className="text-[11px] text-brand-navy/75 mt-0.5">
                          {isCompletion
                            ? `Card completed · ${tx.stamp_count || tx.stamps_at_completion} stamp${(tx.stamp_count || 1) !== 1 ? 's' : ''}`
                            : `${tx.stamp_count || 1} stamp${(tx.stamp_count || 1) !== 1 ? 's' : ''} collected`}
                        </p>
                        <p className="text-[10px] text-brand-navy/40 mt-0.5">
                          {ts ? format(ts.toDate(), 'MMM d, yyyy · h:mm a') : 'Recently'}
                        </p>
                      </div>
                    </div>
                  );
                })}
                {transactions.length === 0 && (
                  <div className="py-12 text-center text-brand-navy/32">
                    <Clock size={48} className="mx-auto mb-4 opacity-10" />
                    <p className="font-bold">No history yet</p>
                  </div>
                )}
              </div>
            </Modal>
          )}
        </AnimatePresence>
      </motion.div>
    </motion.div>
  );
}

